// src/App.js
import React, { useState } from 'react';
import Login from './components/Login';
import Profile from './components/Profile';

function App() {
  const [token, setToken] = useState(localStorage.getItem('token'));

  return (
    <div>
      {!token ? (
        <Login setToken={setToken} />
      ) : (
        <Profile token={token} />
      )}
    </div>
  );
}

export default App;
